class Solution:
    def minimumSum(self, n: int, k: int) -> int:
        chosen = set()
        total = 0
        x = 1
        while len(chosen) < n:
            if (k - x) not in chosen:
                chosen.add(x)
                total += x
            x += 1
        return total
