def ref(inp):
    t = inp.split()
    n, k = int(t[0]), int(t[1])
    # Exhaustive search over sets of n distinct positive integers drawn from
    # 1..LIM (LIM = 2*(k+n) is far above where an optimal set can lie), keeping
    # only sets where no two distinct elements sum to k. Minimise the sum.
    LIM = 2 * (k + n)
    best = [None]

    def rec(start, chosen, s):
        if len(chosen) == n:
            if best[0] is None or s < best[0]:
                best[0] = s
            return
        for v in range(start, LIM + 1):
            # prune: remaining picks are at least v, v+1, ...
            remaining = n - len(chosen)
            lower = s + sum(range(v, v + remaining))
            if best[0] is not None and lower >= best[0]:
                break
            ok = True
            for c in chosen:
                if c + v == k:
                    ok = False
                    break
            if not ok:
                continue
            chosen.append(v)
            rec(v + 1, chosen, s + v)
            chosen.pop()

    rec(1, [], 0)
    return str(best[0])
