    t = inp.split()
    n, k = int(t[0]), int(t[1])
    # Any valid array of length n can be taken within [1, k+n]:
    # values >= k never form a pair summing to k with distinct positives,
    # so brute force over all n-subsets of [1, k+n] and minimize the sum.
    best = None
    for comb in combinations(range(1, k + n + 1), n):
        ok = True
        for i in range(n):
            for j in range(i + 1, n):
                if comb[i] + comb[j] == k:
                    ok = False
                    break
            if not ok:
